      "source": "general:warranty_policy",
      "answer": "สวัสดีค่ะ ยินดีให้บริการนะคะ \n\nรายละเอียดการรับประกันสินค้ามีดังนี้นะคะ\n\n1. สินค้ารับประกันตามเงื่อนไขภายในระยะเวลาที่ระบุไว้ในรายละเอียดของสินค้าแต่ละรุ่นค่ะ\n2. กรณีชิ้นส่วนชำรุดเสียหายจากการผลิต ต้องแจ้งภายใน 7 วันหลังได้รับสินค้าค่ะ\n3. หากสินค้าสูญหายจะถือว่าสิ้นสุดการรับประกันทันทีค่ะ\n4. ต้องเก็บกล่องบรรจุภัณฑ์ไว้เพื่อยืนยันการซื้อสินค้าด้วยนะคะ\n5. สินค้าที่หมดประกันแล้วอาจสามารถซ่อมได้บางกรณีโดยมีค่าใช้จ่ายเพิ่มเติมค่ะ\n\nหากต้องการสอบถามข้อมูลเพิ่มเติมฉบับเต็ม สามารถทักแอดมินได้เลยนะคะ",
